  app.get("/api/share/:token", async (req: Request, res: Response) => {
    try {
      const token = (req.params as any).token as string;
      const ip = req.ip || "unknown";
      const lockoutKey = `${ip}:${token}`;
      const now = Date.now();

      const lockoutRecord = sharePasscodeLockouts.get(lockoutKey);
      if (lockoutRecord) {
        if (now - lockoutRecord.lastFailure > SHARE_PASSCODE_WINDOW_MS) {
          sharePasscodeLockouts.delete(lockoutKey);
        } else if (lockoutRecord.lockedUntil > now) {
          const retryAfter = Math.ceil((lockoutRecord.lockedUntil - now) / 1000);
          auditLog(req, "share_passcode_locked", "share_link", token);
          return res.status(423).json({
            error: "Too many incorrect passcode attempts. Please try again later.",
            retryAfter,
            code: "PASSCODE_LOCKED",
          });
        }
      }

      const link = await storage.getShareLinkByToken(token);

      if (!link) {
        return res.status(404).json({ error: "Share link not found" });
      }

      if (link.isRevoked) {
        return res.status(403).json({ error: "Share link has been revoked" });
      }

      if (new Date() > link.expiresAt) {
        return res.status(403).json({ error: "Share link has expired" });
      }

      const providedPasscode = (req.query as any).passcode as string | undefined;
      if (link.passcode) {
        if (!providedPasscode || link.passcode !== providedPasscode) {
          const rec = sharePasscodeLockouts.get(lockoutKey) || { failures: 0, lastFailure: 0, lockedUntil: 0 };
          rec.failures++;
          rec.lastFailure = now;
          applySharePasscodeLockout(rec);
          sharePasscodeLockouts.set(lockoutKey, rec);
          pruneSharePasscodeLockouts(now);
          auditLog(req, "share_passcode_failed", "share_link", link.id);
          if (!providedPasscode) {
            return res.status(401).json({ error: "Passcode required", requiresPasscode: true });
          }
          return res.status(401).json({ error: "Invalid passcode", requiresPasscode: true });
        }
        sharePasscodeLockouts.delete(lockoutKey);
      }

      await storage.incrementShareLinkViews(link.id);
      auditLog(req, "view_share_link", "share_link", link.id);
      
      await storage.createShareLinkAccessLog({
        shareLinkId: link.id,
        action: "viewed",
        accessorIp: req.ip || null,
        accessorUserAgent: getHeader(req, "user-agent") || null,
        metadata: { viewCount: (link.viewCount || 0) + 1 },
      });

      let records = await storage.getHealthRecords(link.userId);

      if (link.recordIds && Array.isArray(link.recordIds)) {
        records = records.filter(r => (link.recordIds as string[]).includes(r.id));
      }

      if (link.categories && Array.isArray(link.categories)) {
        records = records.filter(r => (link.categories as string[]).includes(r.type));
      }

      if (link.dateRangeStart) {
        records = records.filter(r => new Date(r.date) >= new Date(link.dateRangeStart!));
      }

      if (link.dateRangeEnd) {
        records = records.filter(r => new Date(r.date) <= new Date(link.dateRangeEnd!));
      }

      res.json({
        expiresAt: link.expiresAt,
        records,
      });
    } catch (error) {
      res.status(500).json({ error: "Failed to access shared records" });
    }
  });


