  app.post("/api/tefca/query", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const { patient, networkIds, exchangePurpose } = req.body as any;

      if (!patient || !patient.firstName || !patient.lastName || !patient.dateOfBirth) {
        return res.status(400).json({ error: "Patient information required (firstName, lastName, dateOfBirth)" });
      }

      const query: TefcaPatientQuery = {
        firstName: patient.firstName,
        lastName: patient.lastName,
        dateOfBirth: patient.dateOfBirth,
        zipCode: patient.zipCode,
        gender: patient.gender,
      };

      auditLog(req, "tefca_query", "tefca", undefined, { networkIds, exchangePurpose });

      const results = await tefcaClient.queryPatientRecords(query, networkIds, exchangePurpose);

      res.json({
        results,
        totalRecords: results.reduce((sum, r) => sum + r.records.length, 0),
        networksQueried: results.length,
      });
    } catch (error) {
      console.error("TEFCA query error:", error);
      res.status(500).json({ error: "Failed to query TEFCA networks" });
    }
  });


  app.post("/api/tefca/import", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const { queryResults, networkName } = req.body as any;

      if (!queryResults || !queryResults.records || !Array.isArray(queryResults.records)) {
        return res.status(400).json({ error: "Query results with records array required" });
      }

      const source = await storage.createDataSource({
        userId,
        name: networkName || `TEFCA - ${queryResults.networkName || "Unknown Network"}`,
        type: "tefca",
        fhirEndpoint: null,
        isConnected: true,
        lastSyncAt: new Date(),
        recordCount: queryResults.records.length,
        clientId: null,
        accessToken: null,
        refreshToken: null,
        tokenExpiresAt: null,
        patientId: null,
      });

      const importedRecords = [];
      for (const record of queryResults.records) {
        const healthRecord = tefcaClient.mapToHealthRecord(record, userId, source.id);
        const created = await storage.createHealthRecord(healthRecord as InsertHealthRecord);
        importedRecords.push(created);
      }

      await storage.updateDataSource(source.id, { recordCount: importedRecords.length });

      auditLog(req, "tefca_import", "health_records", source.id, { 
        recordCount: importedRecords.length,
        networkId: queryResults.networkId,
      });

      res.status(201).json({
        source,
        importedCount: importedRecords.length,
        records: importedRecords,
      });
    } catch (error) {
      console.error("TEFCA import error:", error);
      res.status(500).json({ error: "Failed to import TEFCA records" });
    }
  });


  app.post("/api/tefca/auto-discover", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const { decryptField: decrypt } = await import("../said-patient-service");
      const encKey = process.env.PHI_ENCRYPTION_KEY;

      const [patient] = await db.select().from(patients).where(eq(patients.userId, userId)).limit(1);
      if (!patient) {
        return res.status(404).json({ error: "Patient profile not found. Complete onboarding first." });
      }

      let firstName: string, lastName: string, dob: string | undefined;
      try {
        if (!encKey) throw new Error("PHI_ENCRYPTION_KEY not set");
        firstName = decrypt(patient.nameFirstEnc, encKey);
        lastName = decrypt(patient.nameLastEnc, encKey);
        dob = patient.dobEnc ? decrypt(patient.dobEnc, encKey) : undefined;
      } catch {
        return res.status(400).json({ error: "Unable to decrypt patient demographics for TEFCA query." });
      }

      if (!dob) {
        return res.status(400).json({ error: "Date of birth is required for TEFCA record discovery." });
      }

      const query: TefcaPatientQuery = {
        firstName,
        lastName,
        dateOfBirth: dob,
        zipCode: patient.residencyState || undefined,
        gender: req.body?.gender,
      };

      auditLog(req, "tefca_auto_discover", "tefca", undefined, {
        exchangePurpose: "T-IAS",
        networksQueried: "all",
      });

      const results = await tefcaClient.queryPatientRecords(query, undefined, "T-IAS");
      const totalRecords = results.reduce((sum, r) => sum + r.records.length, 0);

      if (totalRecords === 0) {
        return res.json({
          discovered: false,
          message: "No records found across TEFCA networks. You can still import manually.",
          networksQueried: results.length,
          totalRecords: 0,
        });
      }

      let importedCount = 0;
      const sourcesCreated: string[] = [];

      for (const networkResult of results) {
        if (networkResult.records.length === 0) continue;

        const source = await storage.createDataSource({
          userId,
          name: `TEFCA - ${networkResult.networkName}`,
          type: "tefca",
          fhirEndpoint: null,
          isConnected: true,
          lastSyncAt: new Date(),
          recordCount: networkResult.records.length,
          clientId: null,
          accessToken: null,
          refreshToken: null,
          tokenExpiresAt: null,
          patientId: null,
        });

        sourcesCreated.push(source.id);

        for (const record of networkResult.records) {
          const healthRecord = tefcaClient.mapToHealthRecord(record, userId, source.id);
          await storage.createHealthRecord(healthRecord as InsertHealthRecord);
          importedCount++;
        }

        await storage.updateDataSource(source.id, { recordCount: networkResult.records.length });
      }

      auditLog(req, "tefca_auto_discover_complete", "health_records", undefined, {
        importedCount,
        networksWithRecords: sourcesCreated.length,
        totalNetworksQueried: results.length,
      });

      res.json({
        discovered: true,
        importedCount,
        networksWithRecords: sourcesCreated.length,
        networksQueried: results.length,
        message: `Found and imported ${importedCount} records from ${sourcesCreated.length} networks.`,
      });
    } catch (error) {
      console.error("TEFCA auto-discover error:", error);
      res.status(500).json({ error: "Failed to auto-discover records via TEFCA" });
    }
  });

