  app.get("/api/fhir/Patient", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const {
        name, family, given, birthdate, identifier,
        gender, phone, email, city, state,
        deceased, "death-date": deathDate,
        _count, _offset, _sort, _include_clinical,
      } = req.query as any;

      const pageSize = Math.min(parseInt(_count as string) || 20, 100);
      const pgOffset = parseInt(_offset as string) || 0;
      const sortField = (_sort as string) || "family";
      const sortDir = sortField.startsWith("-") ? "DESC" : "ASC";
      const sortCol = sortField.replace(/^-/, "");
      const includeClinical = _include_clinical === "true";

      const sortMapping: Record<string, string> = {
        family: "pp.last_name",
        given: "pp.first_name",
        name: "pp.last_name",
        birthdate: "pp.date_of_birth",
        gender: "pp.gender",
        "death-date": "pp.deceased_date",
      };
      const validSortCol = sortMapping[sortCol] || "pp.last_name";
      const validSortDir = sortDir === "DESC" ? "DESC" : "ASC";

      const whereParts: ReturnType<typeof sql>[] = [];
      if (name) {
        const v = `%${(name as string).toLowerCase()}%`;
        whereParts.push(sql`(LOWER(pp.first_name) LIKE ${v} OR LOWER(pp.last_name) LIKE ${v} OR LOWER(CONCAT(COALESCE(pp.first_name,''), ' ', COALESCE(pp.last_name,''))) LIKE ${v})`);
      }
      if (family) {
        whereParts.push(sql`LOWER(pp.last_name) LIKE ${`%${(family as string).toLowerCase()}%`}`);
      }
      if (given) {
        whereParts.push(sql`LOWER(pp.first_name) LIKE ${`%${(given as string).toLowerCase()}%`}`);
      }
      if (birthdate) {
        const bd = birthdate as string;
        if (bd.startsWith("ge")) {
          whereParts.push(sql`pp.date_of_birth >= ${bd.substring(2)}`);
        } else if (bd.startsWith("le")) {
          whereParts.push(sql`pp.date_of_birth <= ${bd.substring(2)}`);
        } else {
          const dateVal = bd.startsWith("eq") ? bd.substring(2) : bd;
          whereParts.push(sql`DATE(pp.date_of_birth) = DATE(${dateVal})`);
        }
      }
      if (identifier) {
        const idVal = `%${(identifier as string).toLowerCase()}%`;
        whereParts.push(sql`EXISTS (SELECT 1 FROM patient_identifiers pi2 WHERE pi2.patient_id = pp.id AND LOWER(pi2.identifier_value) LIKE ${idVal} AND pi2.is_active = true)`);
      }
      if (gender) {
        whereParts.push(sql`LOWER(pp.gender) = ${(gender as string).toLowerCase()}`);
      }
      if (phone) {
        const phoneVal = `%${phone as string}%`;
        whereParts.push(sql`(pp.phone LIKE ${phoneVal} OR pp.mobile_phone LIKE ${phoneVal})`);
      }
      if (email) {
        whereParts.push(sql`LOWER(pp.email) LIKE ${`%${(email as string).toLowerCase()}%`}`);
      }
      if (city) {
        whereParts.push(sql`LOWER(pp.city) LIKE ${`%${(city as string).toLowerCase()}%`}`);
      }
      if (state) {
        whereParts.push(sql`LOWER(pp.state) = ${(state as string).toLowerCase()}`);
      }
      if (deceased) {
        const decVal = (deceased as string).toLowerCase();
        if (decVal === "true") {
          whereParts.push(sql`pp.deceased_boolean = true`);
        } else if (decVal === "false") {
          whereParts.push(sql`(pp.deceased_boolean = false OR pp.deceased_boolean IS NULL)`);
        }
      }
      if (deathDate) {
        const dd = deathDate as string;
        if (dd.startsWith("ge")) {
          whereParts.push(sql`pp.deceased_date >= ${dd.substring(2)}`);
        } else if (dd.startsWith("le")) {
          whereParts.push(sql`pp.deceased_date <= ${dd.substring(2)}`);
        } else {
          const dateVal = dd.startsWith("eq") ? dd.substring(2) : dd;
          whereParts.push(sql`DATE(pp.deceased_date) = DATE(${dateVal})`);
        }
      }

      const whereClause = whereParts.length > 0
        ? sql`WHERE ${sql.join(whereParts, sql` AND `)}`
        : sql``;

      const countResult = await db.execute(sql`SELECT COUNT(*) as total FROM patient_profiles pp ${whereClause}`);
      const totalCount = parseInt((countResult as any).rows?.[0]?.total || "0");

      const orderClause = validSortCol === "pp.last_name" ? sql`ORDER BY pp.last_name ${sql.raw(validSortDir)} NULLS LAST`
        : validSortCol === "pp.first_name" ? sql`ORDER BY pp.first_name ${sql.raw(validSortDir)} NULLS LAST`
        : validSortCol === "pp.date_of_birth" ? sql`ORDER BY pp.date_of_birth ${sql.raw(validSortDir)} NULLS LAST`
        : validSortCol === "pp.gender" ? sql`ORDER BY pp.gender ${sql.raw(validSortDir)} NULLS LAST`
        : validSortCol === "pp.deceased_date" ? sql`ORDER BY pp.deceased_date ${sql.raw(validSortDir)} NULLS LAST`
        : sql`ORDER BY pp.last_name ${sql.raw(validSortDir)} NULLS LAST`;

      const dataResult = includeClinical
        ? await db.execute(sql`
          SELECT pp.*, 
            u.name as user_name, u.email as user_email,
            (SELECT STRING_AGG(pi2.identifier_value || '|' || pi2.identifier_type, ';;') 
             FROM patient_identifiers pi2 
             WHERE pi2.patient_id = pp.id AND pi2.is_active = true) as identifiers,
            (SELECT COUNT(*) FROM health_records hr WHERE hr.user_id = pp.user_id AND hr.fhir_resource_type = 'Condition') as condition_count,
            (SELECT COUNT(*) FROM health_records hr WHERE hr.user_id = pp.user_id AND hr.fhir_resource_type IN ('MedicationRequest', 'MedicationStatement')) as medication_count,
            (SELECT COUNT(*) FROM health_records hr WHERE hr.user_id = pp.user_id AND hr.fhir_resource_type = 'AllergyIntolerance') as allergy_count,
            (SELECT COUNT(*) FROM health_records hr WHERE hr.user_id = pp.user_id AND hr.fhir_resource_type = 'Immunization') as immunization_count,
            (SELECT STRING_AGG(t, ';;') FROM (SELECT DISTINCT hr.title as t FROM health_records hr WHERE hr.user_id = pp.user_id AND hr.fhir_resource_type = 'Condition' ORDER BY t LIMIT 5) sub) as condition_names,
            (SELECT STRING_AGG(t, ';;') FROM (SELECT DISTINCT hr.title as t FROM health_records hr WHERE hr.user_id = pp.user_id AND hr.fhir_resource_type IN ('MedicationRequest', 'MedicationStatement') ORDER BY t LIMIT 5) sub) as medication_names,
            (SELECT STRING_AGG(t, ';;') FROM (SELECT DISTINCT hr.title as t FROM health_records hr WHERE hr.user_id = pp.user_id AND hr.fhir_resource_type = 'AllergyIntolerance' ORDER BY t LIMIT 5) sub) as allergy_names,
            (SELECT STRING_AGG(t, ';;') FROM (SELECT DISTINCT hr.title as t FROM health_records hr WHERE hr.user_id = pp.user_id AND hr.fhir_resource_type = 'Immunization' ORDER BY t LIMIT 5) sub) as immunization_names
          FROM patient_profiles pp
          LEFT JOIN users u ON u.id = pp.user_id
          ${whereClause}
          ${orderClause}
          LIMIT ${pageSize} OFFSET ${pgOffset}
        `)
        : await db.execute(sql`
          SELECT pp.*, 
            u.name as user_name, u.email as user_email,
            (SELECT STRING_AGG(pi2.identifier_value || '|' || pi2.identifier_type, ';;') 
             FROM patient_identifiers pi2 
             WHERE pi2.patient_id = pp.id AND pi2.is_active = true) as identifiers
          FROM patient_profiles pp
          LEFT JOIN users u ON u.id = pp.user_id
          ${whereClause}
          ${orderClause}
          LIMIT ${pageSize} OFFSET ${pgOffset}
        `);
      const rows = (dataResult as any).rows || [];

      const entries = rows.map((row: any) => {
        const identifiers: { type: string; value: string }[] = [];
        if (row.identifiers) {
          row.identifiers.split(";;").forEach((pair: string) => {
            const [value, type] = pair.split("|");
            if (value && type) identifiers.push({ type, value });
          });
        }

        return {
          resourceType: "Patient",
          id: row.id,
          meta: { lastUpdated: row.updated_at },
          active: true,
          name: [{
            use: "official",
            family: row.last_name || "",
            given: [row.first_name || "", row.middle_name || "NMN"].filter(Boolean),
            text: [row.first_name, row.middle_name || "NMN", row.last_name].filter(Boolean).join(" "),
          }],
          gender: row.gender || "unknown",
          birthDate: row.date_of_birth ? new Date(row.date_of_birth).toISOString().split("T")[0] : null,
          telecom: [
            row.phone ? { system: "phone", value: row.phone, use: "home" } : null,
            row.mobile_phone ? { system: "phone", value: row.mobile_phone, use: "mobile" } : null,
            (row.email || row.user_email) ? { system: "email", value: row.email || row.user_email } : null,
          ].filter(Boolean),
          address: (row.address_line_1 || row.city || row.state) ? [{
            line: [row.address_line_1, row.address_line_2].filter(Boolean),
            city: row.city,
            state: row.state,
            postalCode: row.zip_code,
            country: row.country,
          }] : [],
          deceasedBoolean: row.deceased_boolean || false,
          deceasedDateTime: row.deceased_date ? new Date(row.deceased_date).toISOString().split("T")[0] : undefined,
          identifier: identifiers.map((id) => ({
            type: { text: id.type },
            value: id.value,
          })),
          _userId: row.user_id,
          _profileCompleteness: row.profile_completeness,
          ...(includeClinical ? {
            _clinicalSummary: {
              conditions: {
                count: parseInt(row.condition_count || "0"),
                items: row.condition_names ? row.condition_names.split(";;").filter(Boolean) : [],
              },
              medications: {
                count: parseInt(row.medication_count || "0"),
                items: row.medication_names ? row.medication_names.split(";;").filter(Boolean) : [],
              },
              allergies: {
                count: parseInt(row.allergy_count || "0"),
                items: row.allergy_names ? row.allergy_names.split(";;").filter(Boolean) : [],
              },
              immunizations: {
                count: parseInt(row.immunization_count || "0"),
                items: row.immunization_names ? row.immunization_names.split(";;").filter(Boolean) : [],
              },
            },
          } : {}),
        };
      });

      const bundle = {
        resourceType: "Bundle",
        type: "searchset",
        total: totalCount,
        link: [
          { relation: "self", url: `/api/fhir/Patient?_count=${pageSize}&_offset=${pgOffset}` },
          ...(pgOffset + pageSize < totalCount
            ? [{ relation: "next", url: `/api/fhir/Patient?_count=${pageSize}&_offset=${pgOffset + pageSize}` }]
            : []),
          ...(pgOffset > 0
            ? [{ relation: "previous", url: `/api/fhir/Patient?_count=${pageSize}&_offset=${Math.max(0, pgOffset - pageSize)}` }]
            : []),
        ],
        entry: entries.map((resource: any) => ({
          fullUrl: `/api/fhir/Patient/${resource.id}`,
          resource,
          search: { mode: "match" },
        })),
      };

      auditLog(req, "fhir_patient_search", "Patient", undefined, {
        searchParams: { name, family, given, birthdate, identifier, gender, deceased, deathDate },
        resultCount: totalCount,
        includedClinical: includeClinical,
      });

      res.json(bundle);
    } catch (error) {
      console.error("FHIR Patient search error:", error);
      res.status(500).json({ error: "Failed to search patients" });
    }
  });


  app.get("/api/fhir/Patient/:id", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const patientId = (req.params as any).id as string;

      const result = await db.execute(sql`
        SELECT pp.*, u.name as user_name, u.email as user_email
        FROM patient_profiles pp
        LEFT JOIN users u ON u.id = pp.user_id
        WHERE pp.id = ${patientId} AND pp.user_id = ${userId}
        LIMIT 1
      `);

      const row = (result as any).rows?.[0];
      if (!row) {
        return res.status(404).json({
          resourceType: "OperationOutcome",
          issue: [{ severity: "error", code: "not-found", diagnostics: `Patient/${patientId} not found` }],
        });
      }

      const idResult = await db.execute(sql`
        SELECT identifier_type, identifier_value, issuing_authority
        FROM patient_identifiers
        WHERE patient_id = ${patientId} AND is_active = true
      `);
      const identifiers = ((idResult as any).rows || []).map((r: any) => ({
        type: { text: r.identifier_type },
        value: r.identifier_value,
        assigner: r.issuing_authority ? { display: r.issuing_authority } : undefined,
      }));

      const recordCountResult = await db.execute(sql`
        SELECT COUNT(*) as count FROM health_records WHERE user_id = ${row.user_id}
      `);
      const recordCount = parseInt((recordCountResult as any).rows?.[0]?.count || "0");

      const resource = {
        resourceType: "Patient",
        id: row.id,
        meta: { lastUpdated: row.updated_at, versionId: "1" },
        active: true,
        name: [{
          use: "official",
          family: row.last_name || "",
          given: [row.first_name, row.middle_name || "NMN"].filter(Boolean),
          text: [row.first_name, row.middle_name || "NMN", row.last_name].filter(Boolean).join(" "),
        }],
        gender: row.gender || "unknown",
        birthDate: row.date_of_birth ? new Date(row.date_of_birth).toISOString().split("T")[0] : null,
        telecom: [
          row.phone ? { system: "phone", value: row.phone, use: "home" } : null,
          row.mobile_phone ? { system: "phone", value: row.mobile_phone, use: "mobile" } : null,
          (row.email || row.user_email) ? { system: "email", value: row.email || row.user_email } : null,
        ].filter(Boolean),
        address: (row.address_line_1 || row.city || row.state) ? [{
          line: [row.address_line_1, row.address_line_2].filter(Boolean),
          city: row.city,
          state: row.state,
          postalCode: row.zip_code,
          country: row.country,
        }] : [],
        identifier: identifiers,
        maritalStatus: row.marital_status ? { text: row.marital_status } : undefined,
        communication: row.preferred_language ? [{ language: { text: row.preferred_language } }] : [],
        extension: [
          row.race ? { url: "http://hl7.org/fhir/us/core/StructureDefinition/us-core-race", valueString: row.race } : null,
          row.ethnicity ? { url: "http://hl7.org/fhir/us/core/StructureDefinition/us-core-ethnicity", valueString: row.ethnicity } : null,
          row.gender_identity ? { url: "http://hl7.org/fhir/us/core/StructureDefinition/us-core-genderIdentity", valueString: row.gender_identity } : null,
        ].filter(Boolean),
        _userId: row.user_id,
        _profileCompleteness: row.profile_completeness,
        _recordCount: recordCount,
        _bloodType: row.blood_type,
        _organDonor: row.organ_donor,
        _primaryPhysician: row.primary_physician,
        _pharmacy: row.pharmacy,
        _emergencyContacts: row.emergency_contacts,
        _insuranceInfo: row.insurance_info,
      };

      auditLog(req, "fhir_patient_read", "Patient", patientId);
      res.json(resource);
    } catch (error) {
      console.error("FHIR Patient read error:", error);
      res.status(500).json({ error: "Failed to read patient" });
    }
  });

